import {EXAMS,TIERS,campaign,examMastery,examForms,scoreStep} from './exams.mjs?v=exams20261027';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function examsHome(course,game,selected='toeic'){
 const exam=EXAMS.find(e=>e.id===selected)||EXAMS[0],bank=course.examBank;
 return `${game.state.session?`<section class="resume card"><div><b>還有一個未完成的練習</b><p>作答與原始計時已保存，可以接續。</p></div><div class="row"><button class="btn primary" data-act="resume">接續</button><button class="btn ghost" data-act="discard">放棄</button></div></section>`:''}<section class="exam-hero"><p class="eyebrow">考試遠征 · 12 條目標路線</p><h1>把每一關，練成考場上的能力。</h1><p>選考試、定目標，從技能練習走向未見題挑戰，再用官方模考核對成績。</p><div class="exam-tabs" role="group" aria-label="選擇考試">${EXAMS.map(e=>`<button class="chip ${e.id===exam.id?'on':''}" data-act="exam-select" data-id="${e.id}" aria-pressed="${e.id===exam.id}">${e.title}</button>`).join('')}</div></section>
 <section class="card exam-scope"><div><p class="eyebrow">${exam.title} · ${exam.subtitle}</p><h2>${exam.scope}目標</h2><p>${esc(exam.gaps)}</p></div><div class="row"><button class="btn small" data-act="track" data-id="${exam.branch}">完整教材與原有關卡</button><a class="btn small ghost" href="${exam.official}" target="_blank" rel="noopener">官方考試架構 ↗</a></div></section>
 <p class="exam-honesty">分數是自訂備考目標；本站原創題尚未經真人等化校準，不把正確率換算成正式分數，也不保證考試成績。徽章代表本站證據，非官方認證。</p>
 ${!bank?'<section class="card"><h2>題庫載入中</h2><p>正在準備各目標的技能關與挑戰卷。</p><button class="btn" data-act="exam-load">重新載入題庫</button></section>':`<p class="muted small">本次題庫 ${bank.total||bank.campaigns.reduce((n,c)=>n+c.total,0)} 題 · 468 道新增原創題＋既有內容去重整合 · 訓練與挑戰篇章分開</p><div class="exam-campaigns">${TIERS.map((tier,i)=>{
 const key=exam.id+':'+tier.id,m=examMastery(game.state,key),p=game.state.examProgress[key]||{checks:[],official:[]},meta=bank.campaigns.find(c=>c.key===key),ready=m.skills.filter(s=>s.ready).length;
 const forms=examForms(course,game.state,key),nextForm=forms.find(f=>f.fresh)?.form||'A',fresh=forms.filter(f=>f.fresh).length,last=p.checks.filter(r=>r.passed&&r.novel).at(-1),wait=last&&Date.now()-last.at<86400000&&fresh>0;
 return `<article class="exam-campaign ${m.completed?'earned':''}" data-campaign="${key}"><header><span class="exam-medal" aria-hidden="true">${m.completed?tier.medal:'🧭'}</span><div><p class="eyebrow">${tier.title}</p><h2>${exam.unit} ${exam.targets[i]}<small>備考目標</small></h2></div></header><p class="exam-stage">${m.stage}</p><div class="exam-meter" role="progressbar" aria-label="技能關完成數" aria-valuemin="0" aria-valuemax="${m.skills.length}" aria-valuenow="${ready}"><span style="width:${100*ready/m.skills.length}%"></span></div><p class="small">技能印記 ${ready}/${m.skills.length} · 未見卷達標 ${m.checks}/2 · 隔日複測 ${m.spaced?'✓':'待完成'}</p>
 <ol class="exam-skills">${m.skills.map(s=>{const cap=meta.skills.find(x=>x.id===s.id);return `<li class="${s.ready?'ready':''}"><span class="skill-seal">${s.ready?'✓':'◇'}</span><div><b>${s.title}</b><small>近 30 天 ${s.correct}/${s.n} 題獨立答對 · 練習池 ${cap.practice} 題</small></div><button class="btn small" data-act="start" data-mode="exam-practice" data-id="${key}:${s.id}">${s.ready?'再精練':'開始練'}</button></li>`;}).join('')}</ol>
 <details class="exam-rules"><summary>這個目標，怎樣取得印記？</summary><p>每個技能至少練 4 個不同內容，近 30 天獨立正確率達 80%。兩份不同篇章的未見卷均須限時完成、整卷至少 80%、每技能至少 75%，且兩次相隔至少 24 小時。提示、重看舊卷與未完整聽辨不算獨立能力證據。</p><p>技能關自由選擇，本站里程碑不換算正式考試分數。這是技能抽樣挑戰，不是官方全長／適性模考。</p></details>
 <div class="exam-check-action"><button class="btn ${m.next?'':'primary'}" data-act="start" data-mode="exam-check" data-id="${key}" ${wait?'disabled':''}>${wait?'隔日再做未見卷':fresh>0?'⚔️ 未見題挑戰 '+nextForm:'↻ 重做挑戰（已見卷）'}</button><small>${fresh>0?`剩 ${fresh} 份未見卷 · 每卷 ${meta.skills.reduce((n,s)=>n+s.A,0)} 題`:'本站未見卷已用完；可複習，新增證據請做官方模考。'}${m.next?' · 建議先取得技能印記':''}</small></div>
 <details class="exam-evidence"><summary>🎯 官方成績核對 · 已記錄 ${m.official} 個達標日期</summary><p>完成官方模考或實考後，自行登錄此分項成績；來源未由本站驗證。近 90 天兩個不同日期、不同官方試卷均達目標，比單次刷題更能支持備考判斷。</p><a href="${exam.practice}" target="_blank" rel="noopener">前往官方備考工具 ↗</a><form data-form="exam-evidence" data-key="${key}"><label>分項成績（${exam.range[0]}–${exam.range[1]}）<input name="score" type="number" min="${exam.range[0]}" max="${exam.range[1]}" step="${scoreStep(exam.id)}" required></label><label>官方卷號／實考場次<input name="form" type="text" minlength="2" maxlength="80" placeholder="例如 Bluebook Test 1" required></label><label>測驗日期<input name="date" type="date" max="${game.today()}" required></label><label>來源<select name="kind"><option value="practice">官方模考 · 自行登錄</option><option value="actual">正式實考 · 自行登錄</option></select></label><button class="btn small" type="submit">儲存成績</button><p class="exam-save-status" role="status"></p></form><ul>${(p.official||[]).slice().reverse().map(r=>`<li>${esc(r.date)} · ${r.score} · ${esc(r.form||'未填卷號')} · ${r.kind==='actual'?'實考':'官方模考'}（自填）</li>`).join('')}</ul></details>
 </article>`;
 }).join('')}</div>`}`;
}
export function examResult(r){
 const c=campaign(r.ref);return `<div class="result exam-result"><p class="eyebrow">${c.exam.title} · ${c.level.title} · ${c.exam.unit} ${c.target} 目標</p><h1>${r.mode==='exam-check'?r.passed?'未見題挑戰達標':'找到下一個練習重點':r.passed?'技能又向前一步':'把線索帶回下一關'}</h1><p class="lead">獨立答對 ${r.firstTry}/${r.total} · +${r.xp} XP</p><p class="exam-honesty">這是本站技能表現，不是正式分數預測。${r.mode==='exam-check'?(!r.novel?'本卷已有篇章曝光，只作複習，不計新能力證據。':!r.timed?'超過本卷時間目標，先練熟再用官方新卷核對。':'本卷按目標節奏完成。'):''}</p><div class="exam-result-skills">${r.skills.map(s=>`<p><b>${s.title}</b><span>${s.correct}/${s.n}</span></p>`).join('')}</div><p>${r.mastery.stage}</p><p class="small">${r.mastery.completed?'已取得本站里程碑，請接續官方模考核對。':'技能印記＋兩份未見卷＋至少隔日複測，逐步建立證據。'}</p><details class="placement-review"><summary>逐題答案、線索與解說（${r.review.length}）</summary>${r.review.map((q,i)=>`<article><h3>${i+1}. ${q.ok?'✓':'再練一次'} ${esc(q.prompt)}</h3>${q.text?`<p lang="en">${esc(q.text)}</p>`:''}<p>你的答案：${esc(q.value)}${q.unheard?'（未取得完整聽辨證據）':''}</p><p><b>正確答案：${esc(q.answer.replaceAll(' || ',' ＋ '))}</b></p><p>${esc(q.why)}</p><button class="say" data-act="prompt-say" data-text="${esc(q.why)}" aria-label="朗讀解說">🔊</button></article>`).join('')}</details><button class="btn primary big" data-act="exam-home" data-id="${c.exam.id}">回到考試遠征</button></div>`;
}
